import Testing

@testable import GrafixCore

// Expected coordinates generated by running the unmodified upstream _doubleLine
// and Random functions in Node at Rough.js commit 56a2762171b1294d643501e8d14f120db6b27bd7.
@Test func roughLineMatchesUpstreamGeometry() {
  let cases: [(Double, Double, UInt32, Bool, Bool, [[Double]])] = [
    (
      3, 4, 1, false, false,
      [
        [0.21431586192920804, 0.2409711848013103],
        [
          0.4868776267021895, 1.0847311043087393, 1.0267986493743957, 1.1614150275383146,
          2.8016013358719647, 4.098083875607699,
        ], [-0.1621663908008486, 0.06614965223707259],
        [
          0.7647873921785504, 1.0758809584192932, 1.3405780137982222, 1.8188703722320498,
          2.8549064283724874, 4.188203968340531,
        ],
      ]
    ),
    (
      250, 100, 42, false, false,
      [
        [-1.5650952170730597, -1.1900138541255383],
        [
          50.60662772997608, 20.07714690440205, 99.00981298548052, 42.04157793590829,
          250.5248726535881, 98.8060101692335,
        ], [-0.19139002544949424, 0.08876345434446363],
        [
          73.30756918903016, 30.733319096187888, 148.42149281561154, 60.46912442745215,
          250.4897690871448, 100.48505145812668,
        ],
      ]
    ),
    (
      700, -200, 2_147_483_647, true, false,
      [
        [-0.3429053790867329, -0.3855538956820965],
        [
          279.46080653630196, -79.89693137668073, 559.553807567805, -158.73869776464997,
          700.3174378626048, -200.15693420097233,
        ],
      ]
    ),
    (
      100, 50, 123, false, true,
      [
        [0, 0],
        [21.457690974231813, 7.65872964076698, 40.739862299989916, 18.198619521223012, 100, 50],
        [0, 0],
        [25.44999706512317, 12.830866700969636, 50.766186635475606, 25.431046260520816, 100, 50],
      ]
    ),
  ]
  for (x2, y2, seed, single, preserve, expected) in cases {
    var generator = RoughLineGenerator(
      options: .init(seed: seed, disableMultiStroke: single, preserveVertices: preserve))
    let actual = generator.line(x1: 0, y1: 0, x2: x2, y2: y2)
    #expect(actual.count == expected.count)
    for (index, pair) in zip(actual, expected).enumerated() {
      #expect(pair.0.kind == (index.isMultiple(of: 2) ? .move : .bcurveTo))
      #expect(pair.0.data.count == pair.1.count)
      for (coordinate, upstream) in zip(pair.0.data, pair.1) {
        #expect(abs(coordinate - upstream) < 1e-12)
      }
    }
  }
}
